#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
GH_REPO="${GH_REPO:-}" # owner/repo for gh writes; empty = infer from cwd
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# _gh_ready — gh installed and authenticated?
_gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# preflight_gh — prove gh can actually reach the repo BEFORE any stage asks for
# a credential. A token that cannot resolve the repo must fail here, not after
# the human has minted a password. Call once, right after banner.
preflight_gh() {
  local out="" rc=0
  if ! command -v gh >/dev/null 2>&1; then
    warn "gh not installed — secrets will be skipped"; return 1
  fi
  if ! gh auth status >/dev/null 2>&1; then
    warn "gh not authenticated — run: gh auth login"; return 1
  fi
  if [[ -n "$GH_REPO" ]]; then
    out=$(gh repo view "$GH_REPO" --json nameWithOwner 2>&1 >/dev/null) || rc=$?
  else
    out=$(gh repo view --json nameWithOwner 2>&1 >/dev/null) || rc=$?
  fi
  (( rc == 0 )) && return 0
  warn "gh cannot reach ${GH_REPO:-the current repo}: ${out%%$'\n'*}"
  note "fix the token scope now, or every secret below will be skipped"
  return 1
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh, targeting
# $GH_REPO when set. Reports gh's own error rather than hiding it: a silent
# "skipped" reads as done and is how a wizard finishes with nothing written.
set_secret() {
  local name="$1" value="$2" err="" rc=0
  if ! _gh_ready; then
    err="gh not installed or not authenticated"; rc=1
  elif [[ -n "$GH_REPO" ]]; then
    err=$(printf '%s' "$value" | gh secret set "$name" --repo "$GH_REPO" 2>&1 >/dev/null) || rc=$?
  else
    err=$(printf '%s' "$value" | gh secret set "$name" 2>&1 >/dev/null) || rc=$?
  fi
  if (( rc == 0 )); then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
    return 0
  fi
  err="${err%%$'\n'*}"; [[ -n "$err" ]] || err="gh exited $rc"
  SKIPPED+=("GitHub secret $name — $err")
  warn "skipped GitHub secret $name: $err"
  return 0
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2" err="" rc=0
  if ! _gh_ready; then
    err="gh not installed or not authenticated"; rc=1
  elif [[ -n "$GH_REPO" ]]; then
    err=$(gh variable set "$name" --repo "$GH_REPO" --body "$value" 2>&1 >/dev/null) || rc=$?
  else
    err=$(gh variable set "$name" --body "$value" 2>&1 >/dev/null) || rc=$?
  fi
  if (( rc == 0 )); then
    printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
    return 0
  fi
  err="${err%%$'\n'*}"; [[ -n "$err" ]] || err="gh exited $rc"
  SKIPPED+=("GitHub variable $name — $err")
  warn "skipped GitHub variable $name: $err"
  return 0
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES — ta-legacy-docs: copy TA's NAS folders to the NYC droplet nightly
# over WireGuard, then point the app at them (LEGACY_DOCS_DIR).
#
# Secrets (WireGuard private/preshared key, NAS login) go ask_secret → ssh
# STDIN → a root-only file on the droplet. Never argv, never ENV_FILE.
# ENV_FILE below holds only non-secret answers so re-runs offer defaults.
# ──────────────────────────────────────────────────────────────────────────

# Braces + exit: bash parses the whole block before running it, so saving an
# edit to this file mid-run can't make bash resume at a stale byte offset.
{
TOTAL_STAGES=7
TOTAL_MINUTES=40

mkdir -p "$HOME/.config"
ENV_FILE="$HOME/.config/ta-legacy-docs-wizard.env" # non-secret answers only
HOST=104.236.20.89                                  # bcns-web-apps-nyc (nyc3)
KEY="$HOME/.ssh/id_ed25519_bcns"
DEST=/srv/ta/legacy-docs
R() { ssh -i "$KEY" -o BatchMode=yes -o ConnectTimeout=10 "root@$HOST" "$@"; }
die() { printf '\n'; warn "$1"; note "Nothing secret was saved locally. Fix it, then re-run this wizard."; exit 1; }

banner "TA legacy NAS docs → droplet"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight — droplet reachable, disk, app user" 2
R true || die "ssh root@$HOST with $KEY failed. Fix ssh first."
say "ssh to $HOST works."
FREE_KB=$(R "df -Pk /srv | awk 'NR==2{print \$4}'")
say "Free on /srv: $((FREE_KB / 1024 / 1024)) GB (the three folders are ~1.8 GB)."
(( FREE_KB > 4 * 1024 * 1024 )) || die "Under 4 GB free on /srv — free space before copying."
APP_USER=$(R "systemctl show -p User --value bcns-app@ta"); APP_USER=${APP_USER:-root}
say "bcns-app@ta runs as: $APP_USER"
R "ufw status 2>/dev/null | head -1" | sed 's/^/  ufw: /' || true
pause "Looks right? Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "WireGuard tunnel to the TA office" 8
if R "systemctl is-active --quiet wg-quick@ta" \
  && say "A tunnel is already up, using Address $(R "ip -br -4 addr show ta | awk '{print \$3}'")." \
  && confirm "Is that exactly the Address in Kalpna's NEW config? (y skips this stage)"; then
  note "kept the existing tunnel"
else
  confirm "Do you have Kalpna's WireGuard peer config (the [Interface]/[Peer] text)?" \
    || die "Peer config still pending from Kalpna. Re-run this wizard when it arrives."
  say "Open the config in a text editor (not a terminal). You'll copy fields one at a time."
  note "Use the NEW peer Kalpna made for the droplet, not the shared staff one."
  note "Address, PublicKey and PresharedKey may differ from last time: re-type them, don't just press Enter."
  note "We set AllowedIPs ourselves and drop DNS=, so the droplet's internet never routes via the office."
  ask WG_ADDRESS "[Interface] Address (e.g. 10.8.0.5/32):"
  ask WG_PEER_PUBKEY "[Peer] PublicKey:"
  ask_secret WG_PSK "[Peer] PresharedKey (hidden; Enter if the config has none):"
  ask WG_ENDPOINT "[Peer] Endpoint (host:port):"
  ask WG_ALLOWED "Office route [default 192.168.254.25/32 — just the NAS]:"
  WG_ALLOWED=${WG_ALLOWED:-192.168.254.25/32}
  [[ "$WG_ALLOWED" == 0.0.0.0/0* || "$WG_ALLOWED" == *::/0* ]] && die "AllowedIPs must not be a default route — it would take every app offline."
  # A WireGuard key is 43 base64 chars + "="; double-click selection drops the "=", so put it back.
  wg_key() { local k="${1//[[:space:]]/}"; [[ "$k" =~ ^[A-Za-z0-9+/]{43}$ ]] && k+="="; [[ "$k" =~ ^[A-Za-z0-9+/]{43}=$ ]] && printf '%s' "$k"; }
  WG_PEER_PUBKEY=$(wg_key "$WG_PEER_PUBKEY") || die "[Peer] PublicKey isn't a WireGuard key (44 chars ending in =)."
  if [[ -n "$WG_PSK" ]]; then WG_PSK=$(wg_key "$WG_PSK") || die "PresharedKey isn't a WireGuard key (44 chars ending in =)."; fi
  [[ -n "$WG_ADDRESS" && -n "$WG_ENDPOINT" ]] || die "A required WireGuard field was empty."
  write_env WG_ADDRESS "$WG_ADDRESS"; write_env WG_PEER_PUBKEY "$WG_PEER_PUBKEY"
  write_env WG_ENDPOINT "$WG_ENDPOINT"; write_env WG_ALLOWED "$WG_ALLOWED"
  say "Installing wireguard-tools, cifs-utils, rsync…"
  R "DEBIAN_FRONTEND=noninteractive apt-get install -y -qq wireguard-tools cifs-utils rsync >/dev/null" || die "apt-get install failed."
  if confirm "Does Kalpna's config contain an [Interface] PrivateKey line?"; then
    ask_secret WG_PRIVATE_KEY "[Interface] PrivateKey (hidden):"
    WG_PRIVATE_KEY=$(wg_key "$WG_PRIVATE_KEY") || die "PrivateKey isn't a WireGuard key (44 chars ending in =)."
    # stdin only (printf is a builtin: no argv); replaces any key the droplet made earlier.
    printf '%s\n' "$WG_PRIVATE_KEY" | R "set -eu; umask 077; mkdir -p /etc/wireguard; cat > /etc/wireguard/ta.key" \
      || die "Writing the private key to the droplet failed."
    unset WG_PRIVATE_KEY
    say "Private key saved on the droplet (root-only)."
  else
    # Generated on the droplet and never printed; re-runs reuse it, so Kalpna's copy of the public key stays valid.
    DROPLET_PUB=$(R "set -eu; umask 077; mkdir -p /etc/wireguard
      [ -s /etc/wireguard/ta.key ] || wg genkey > /etc/wireguard/ta.key
      wg pubkey < /etc/wireguard/ta.key") || die "Generating the droplet key failed."
    say "Send Kalpna this public key for the droplet's peer:"
    printf '\n    %s%s%s\n\n' "$BOLD" "$DROPLET_PUB" "$RESET"
    pause "Enter once Kalpna confirms she's added it"
  fi
  # The PSK travels on stdin (printf is a builtin: no argv), the rest are public values.
  printf '%s\n' "$WG_PSK" | R "set -eu
    read -r psk || true
    umask 077; pk=\$(cat /etc/wireguard/ta.key)
    { printf '[Interface]\nPrivateKey = %s\nAddress = %s\n\n[Peer]\nPublicKey = %s\n' \"\$pk\" '$WG_ADDRESS' '$WG_PEER_PUBKEY'
      [ -n \"\$psk\" ] && printf 'PresharedKey = %s\n' \"\$psk\"
      printf 'Endpoint = %s\nAllowedIPs = %s\nPersistentKeepalive = 25\n' '$WG_ENDPOINT' '$WG_ALLOWED'
    } > /etc/wireguard/ta.conf
    chmod 600 /etc/wireguard/ta.conf
    systemctl enable wg-quick@ta >/dev/null 2>&1; systemctl restart wg-quick@ta" \
    || { R "journalctl -u wg-quick@ta -n 15 --no-pager" | sed -E 's#[A-Za-z0-9+/]{40,}=?#<key hidden>#g; s/^/    /'
         die "wg-quick@ta didn't start (log above, keys hidden)."; }
  unset WG_PSK
fi
say "Checking the tunnel…"
R "wg show ta latest-handshakes" | sed 's/^/  handshake: /' || die "No ta interface: wg-quick@ta isn't up. Re-run this stage."
if R "ping -c2 -W3 192.168.254.25 >/dev/null && timeout 5 bash -c '</dev/tcp/192.168.254.25/445'"; then
  say "${GREEN}NAS 192.168.254.25 reachable, SMB port 445 open.${RESET}"
else
  warn "NAS not reachable over the tunnel. Check: handshake above (0 = no handshake), the DO cloud firewall"
  warn "allows outbound UDP to the endpoint, and Kalpna's side lets this peer reach 192.168.254.25:445."
  die "Fix the tunnel, then re-run (Enter keeps the saved answers)."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "NAS read-only login + test mount" 5
if R "test -s /root/.ta-nas.cred" && confirm "/root/.ta-nas.cred already exists. Keep it?"; then
  note "kept the existing credentials file"
else
  say "Open Kalpna's Bitwarden Send yourself (not via Claude) and copy the read-only NAS user."
  ask_secret NAS_USER "NAS username (hidden):"
  ask_secret NAS_PASS "NAS password (hidden):"
  ask NAS_DOMAIN "NAS domain/workgroup (Enter if none):"
  [[ -n "$NAS_USER" && -n "$NAS_PASS" ]] || die "Username and password are both required."
  write_env NAS_DOMAIN "$NAS_DOMAIN"
  printf '%s\n%s\n' "$NAS_USER" "$NAS_PASS" | R "set -eu
    read -r u; read -r p; umask 077
    { printf 'username=%s\npassword=%s\n' \"\$u\" \"\$p\"; [ -n '$NAS_DOMAIN' ] && printf 'domain=%s\n' '$NAS_DOMAIN'; } > /root/.ta-nas.cred
    chmod 600 /root/.ta-nas.cred" || die "Could not write /root/.ta-nas.cred."
  unset NAS_USER NAS_PASS
fi
ask NAS_SHARE "SMB share [default //192.168.254.25/TECH_ASSOC_DOCUMENTS]:"
NAS_SHARE=${NAS_SHARE:-//192.168.254.25/TECH_ASSOC_DOCUMENTS}
write_env NAS_SHARE "$NAS_SHARE"
NAS_VERS=""
for v in 3.0 2.1 2.0; do
  if R "mkdir -p /mnt/ta-nas; mountpoint -q /mnt/ta-nas && umount /mnt/ta-nas
        timeout 30 mount -t cifs '$NAS_SHARE' /mnt/ta-nas -o ro,credentials=/root/.ta-nas.cred,vers=$v,noserverino" 2>/dev/null; then
    NAS_VERS=$v; break
  fi
done
if [[ -z "$NAS_VERS" ]]; then
  warn "Mount failed with SMB 3.0, 2.1 and 2.0. Last error:"
  R "timeout 30 mount -t cifs '$NAS_SHARE' /mnt/ta-nas -o ro,credentials=/root/.ta-nas.cred,vers=2.0 2>&1; dmesg | grep -i cifs | tail -3" | sed 's/^/    /' || true
  note "Wrong share name or login → re-run. NAS only speaks SMB1 → ask Nate before enabling vers=1.0."
  die "NAS share did not mount."
fi
write_env NAS_VERS "$NAS_VERS"
say "${GREEN}Mounted read-only with SMB $NAS_VERS.${RESET} Top level of the share:"
R "ls -1 /mnt/ta-nas | head -40" | sed 's/^/    /'
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Pick the three folders" 3
say "Paths are relative to the share root you just saw. Look deeper with:"
note "  ssh -i $KEY root@$HOST 'ls /mnt/ta-nas/<folder>'"
ask NAS_SCANNED "ScannedDocs folder [default ScannedDocs]:"; NAS_SCANNED=${NAS_SCANNED:-ScannedDocs}
ask NAS_BILLS "Bills folder [default Bills]:";               NAS_BILLS=${NAS_BILLS:-Bills}
ask NAS_SERVAUTH "ServAuth folder [default ServAuth]:";      NAS_SERVAUTH=${NAS_SERVAUTH:-ServAuth}
for d in "$NAS_SCANNED" "$NAS_BILLS" "$NAS_SERVAUTH"; do
  n=$(R "find '/mnt/ta-nas/$d' -type f 2>/dev/null | wc -l") || n=0
  (( n > 0 )) || die "'/mnt/ta-nas/$d' has no files — check the folder name and re-run."
  say "$d: $n files"
done
write_env NAS_SCANNED "$NAS_SCANNED"; write_env NAS_BILLS "$NAS_BILLS"; write_env NAS_SERVAUTH "$NAS_SERVAUTH"
R "cat > /etc/ta-legacy-docs.conf <<EOF
NAS_SHARE='$NAS_SHARE'
NAS_VERS='$NAS_VERS'
NAS_SCANNED='$NAS_SCANNED'
NAS_BILLS='$NAS_BILLS'
NAS_SERVAUTH='$NAS_SERVAUTH'
EOF
umount /mnt/ta-nas"
say "Saved /etc/ta-legacy-docs.conf (no secrets in it) and unmounted."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Nightly copy timer + first copy" 15
say "Installing /usr/local/sbin/ta-legacy-docs-sync and a 02:30 America/New_York timer…"
R "cat > /usr/local/sbin/ta-legacy-docs-sync" <<'SYNC'
#!/bin/bash
# Copies TA's three NAS folders to /srv/ta/legacy-docs. Mounts the share read-only
# only for the copy. Refuses an empty source so a bad mount can't --delete the copy.
set -euo pipefail
. /etc/ta-legacy-docs.conf
MNT=/mnt/ta-nas DEST=/srv/ta/legacy-docs
mkdir -p "$MNT" "$DEST"
mountpoint -q "$MNT" || timeout 60 mount -t cifs "$NAS_SHARE" "$MNT" \
  -o ro,credentials=/root/.ta-nas.cred,vers="$NAS_VERS",noserverino
trap 'umount "$MNT" 2>/dev/null || true' EXIT
for pair in "ScannedDocs:$NAS_SCANNED" "Bills:$NAS_BILLS" "ServAuth:$NAS_SERVAUTH"; do
  name=${pair%%:*} src="$MNT/${pair#*:}"
  [ -n "$(find "$src" -type f -print -quit 2>/dev/null)" ] || { echo "refusing: $src is empty or missing" >&2; exit 1; }
  rsync -rt --delete-after --no-links --chmod=D755,F644 "$src/" "$DEST/$name/" || [ $? -eq 24 ]  # 24 = files vanished mid-copy: a warning, not a failure
  echo "$name: $(find "$DEST/$name" -type f | wc -l) files"
done
chmod 755 "$DEST"
SYNC
R "chmod 700 /usr/local/sbin/ta-legacy-docs-sync
cat > /etc/systemd/system/ta-legacy-docs-sync.service <<'EOF'
[Unit]
Description=Copy TA legacy NAS documents to /srv/ta/legacy-docs
After=network-online.target wg-quick@ta.service
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/ta-legacy-docs-sync
TimeoutStartSec=2h
EOF
cat > /etc/systemd/system/ta-legacy-docs-sync.timer <<'EOF'
[Unit]
Description=Nightly TA legacy NAS document copy

[Timer]
OnCalendar=*-*-* 02:30:00 America/New_York
Persistent=true

[Install]
WantedBy=timers.target
EOF
systemctl daemon-reload && systemctl enable --now ta-legacy-docs-sync.timer >/dev/null 2>&1" || die "Installing the timer failed."
say "Running the first copy (~1.8 GB; several minutes over the VPN)…"
R "systemctl start ta-legacy-docs-sync.service" || { R "journalctl -u ta-legacy-docs-sync -n 20 --no-pager" | sed 's/^/    /'; die "First copy failed (log above)."; }
R "journalctl -u ta-legacy-docs-sync -n 6 --no-pager -o cat" | sed 's/^/    /'
note "Expect ScannedDocs ≈ 4,651 files."
say "Extensions in Bills and ServAuth (the app tries .pdf, .docx, .doc):"
R "for d in Bills ServAuth; do echo \"\$d:\"; find $DEST/\$d -type f | sed -n 's/.*\\.//p' | tr A-Z a-z | sort | uniq -c | sort -rn | head -5; find $DEST/\$d -type f | head -3; done" | sed 's/^/    /'
R "find $DEST -mindepth 2 -type d | head -5" | sed 's/^/    subfolder: /'
note "Subfolders are fine: the app matches names anywhere under each folder."
[[ "$APP_USER" == root ]] || R "runuser -u '$APP_USER' -- test -r $DEST/ScannedDocs" || die "$APP_USER can't read $DEST/ScannedDocs — fix /srv/ta permissions."
R "systemctl list-timers ta-legacy-docs-sync.timer --no-pager | head -2" | sed 's/^/    /'
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Point the app at the copy" 3
confirm "Is the legacy-docs PR merged, and has deploy.yml finished green?" \
  || { SKIPPED+=("Re-run after the PR deploys to finish stages 6–7 (stages 1–5 are idempotent; Enter keeps answers)"); finish; exit 0; }
OLD_PID=$(R "systemctl show -p MainPID --value bcns-app@ta")
R "set -eu; f=/srv/ta/env
   if grep -q '^LEGACY_DOCS_DIR=' \"\$f\"; then sed -i 's|^LEGACY_DOCS_DIR=.*|LEGACY_DOCS_DIR=$DEST|' \"\$f\"; else echo 'LEGACY_DOCS_DIR=$DEST' >> \"\$f\"; fi
   systemctl restart bcns-app@ta; sleep 4; systemctl is-active --quiet bcns-app@ta" \
  || { R "journalctl -u bcns-app@ta -n 30 --no-pager" | sed 's/^/    /'; die "bcns-app@ta did not come back."; }
NEW_PID=$(R "systemctl show -p MainPID --value bcns-app@ta")
[[ "$NEW_PID" != "$OLD_PID" && "$NEW_PID" != 0 ]] || die "pid did not change ($OLD_PID → $NEW_PID): the restart didn't take."
say "${GREEN}LEGACY_DOCS_DIR set; bcns-app@ta restarted (pid $OLD_PID → $NEW_PID).${RESET}"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Open one legacy document" 3
say "Newest scans on disk (these should be in the Documents list's newest 500):"
R "ls -t $DEST/ScannedDocs | head -3" | sed 's/^/    /'
open_url "https://ta.bcn-services.com/documents"
step "Find one of those names in the list (Ctrl-F), click it."
step "It should open the scan, not 'That document is not available on this case.'"
if confirm "Did the legacy document open?"; then
  say "${GREEN}Legacy NAS documents are live.${RESET}"
else
  R "journalctl -u bcns-app@ta -n 30 --no-pager | grep -i -E 'legacy|document|error'" | sed 's/^/    /' || true
  SKIPPED+=("Legacy doc did not open — send Claude the log lines above (no secrets in them)")
fi

finish
exit
}
